<?php
/** Existing shared catalog edits against disposable native WordPress/WooCommerce storage. */
if(!defined('ABSPATH')||!class_exists('WooCommerce')){return;}
if(str_ends_with((string)wp_parse_url(home_url(),PHP_URL_HOST),'yorohq.com')){throw new RuntimeException('Disposable fixture required.');}
$assert=static function($ok,$why){if(!$ok){throw new RuntimeException($why);}};
global $wpdb;$oldUser=get_current_user_id();$wpdb->query('START TRANSACTION');
try{
 wp_set_current_user((int)get_users(['role'=>'administrator','number'=>1,'fields'=>'ID'])[0]);YoRo_WordPress_Actor::record_access(['assigned'=>true,'status'=>'active','role'=>'store_admin','permissions'=>['yoro_view_store_data','yoro_execute_actions']]);YoRo_Product_Lifecycle::register();
 $params=static fn($id,$kind,$changes)=>['target_id'=>$id,'changes'=>$changes,'expected_version'=>YoRo_Catalog_Management::context($id,$kind)['version']];
 $execute=static function($action,$params,$fence=null){return YoRo_Early_Access_Commerce_Write::execute(['action'=>$action,'params'=>$params,'workflow_id'=>wp_generate_uuid4(),'operation_id'=>'operation_1','authorization'=>['execution_permit'=>'disposable'],'extensions'=>['yoro.mcp_early_access_commerce_write'=>['source_operation_id'=>'envelope_'.str_repeat('a',64),'source_result_hash'=>str_repeat('b',64),'expected_version'=>$params['expected_version']]]],$fence);};
 $suffix=substr(wp_generate_uuid4(),0,8);$parent=wp_insert_term('Parent '.$suffix,'product_cat');$child=wp_insert_term('Child '.$suffix,'product_cat',['parent'=>(int)$parent['term_id']]);$id=(int)$parent['term_id'];
 $product=new WC_Product_Simple();$product->set_name('Assigned fixture');$product->save();wp_set_object_terms($product->get_id(),[$id],'product_cat');
 $before=YoRo_Catalog_Management::context($id,'category');$assert($before['assignment_count']===1,'Context counts existing assignments.');
 $cycle=$params($id,'category',['parent_id'=>(int)$child['term_id']]);$assert(is_wp_error($execute('products.update_category',$cycle))&&(int)get_term($id)->parent===0&&(int)get_term((int)$child['term_id'])->parent===$id,'Cycles reject before native hierarchy repair can mutate any term.');
 $edit=$params($id,'category',['name'=>'Renamed '.$suffix,'description'=>"Exact description\nSecond line"]);$assert(is_wp_error(YoRo_Catalog_Management::write($edit,'products.update_category')),'Callbacks require confirmation.');$assert(is_wp_error($execute('products.update_category',$edit,static fn()=>false)),'Catalog writes honor final execution fence.');
 $result=$execute('products.update_category',$edit);$assert(!is_wp_error($result),'Native category rename succeeds: '.wp_json_encode($result));$after=YoRo_Catalog_Management::context($id,'category');$assert($after['slug']===$before['slug']&&$after['assignment_fingerprint']===$before['assignment_fingerprint']&&$after['name']===$edit['changes']['name'],'Rename preserves exact slug and assignments.');$assert(is_wp_error($execute('products.update_category',$edit)),'Old source version rejects replay.');
 $tag=wp_insert_term('Tag '.$suffix,'product_tag');$tagId=(int)$tag['term_id'];$assert(!is_wp_error($execute('products.update_tag',$params($tagId,'tag',['description'=>'Tag description']))),'Existing tag edits native term.');
 $attributeId=wc_create_attribute(['name'=>'Size '.$suffix,'slug'=>'size'.$suffix,'type'=>'select','order_by'=>'menu_order','has_archives'=>true]);$assert(!is_wp_error($attributeId),'Create disposable attribute.');$taxonomy=wc_attribute_taxonomy_name('size'.$suffix);register_taxonomy($taxonomy,['product'],['hierarchical'=>false]);$term=wp_insert_term('Small',$taxonomy);wp_set_object_terms($product->get_id(),[(int)$term['term_id']],$taxonomy);
 $variation=new WC_Product_Variation();$variation->set_parent_id($product->get_id());$variation->set_attributes([$taxonomy=>'small']);$variation->save();$source=YoRo_Catalog_Management::context($attributeId,'global_attribute');$assert($source['assignment_count']===1&&$source['variation_count']===1,'Global attribute impact covers assignments and variation metadata.');
 $edit=$params($attributeId,'global_attribute',['name'=>'New size '.$suffix,'order_by'=>'name_num']);$result=$execute('products.update_global_attribute',$edit);$assert(!is_wp_error($result),'Native attribute label/sort edit succeeds: '.wp_json_encode($result));$after=YoRo_Catalog_Management::context($attributeId,'global_attribute');foreach(['slug','attribute_type','has_archives','assignment_fingerprint','variation_fingerprint']as$field){$assert($source[$field]===$after[$field],'Protected attribute identity preserved: '.$field);}
 $lifecycle=['product_id'=>$product->get_id(),'changes'=>['purchase_note'=>"Thank you\nExact note",'sold_individually'=>true],'expected_version'=>YoRo_Commerce_Discovery_Service::product_version(wc_get_product($product->get_id()))];$assert(!is_wp_error($execute('products.update_lifecycle',$lifecycle)),'Existing product settings use lifecycle executor.');$fresh=wc_get_product($product->get_id());$assert($fresh->get_purchase_note('edit')==="Thank you\nExact note"&&$fresh->get_sold_individually('edit')===true,'Exact purchase note and sold individually persist.');
 echo "Native catalog edit and purchase settings smoke passed.\n";
}finally{$wpdb->query('ROLLBACK');wp_cache_flush();wp_set_current_user($oldUser);}
